export default function BlizPlates() {
    const [message, setMessage] = useState('');

    async function copyCode(code, label) {
        try {
            await navigator.clipboard.writeText(code);
            setMessage(`${label} copied!`);
        } catch {
            setMessage('Could not copy. Select the code and copy it manually.');
        }
    }

    return (
        <div className="bliz-plates">
            <style>{`
                .bliz-plates { max-width: 720px; margin: 32px auto; padding: 16px; }
                .bliz-plates h2 { margin-bottom: 8px; font-size: 20px; }
                .bliz-plates p { color: #98a3c7; font-size: 14px; }
                .bliz-plates section { margin-top: 20px; }
                .bliz-plates h3 { margin-bottom: 8px; font-size: 15px; }
                .bliz-plates button {
                    display: block; width: 100%; padding: 14px; text-align: left;
                    color: #eaeef6; background: #191e32; border: 1px solid #38405a;
                    border-radius: 8px; cursor: pointer;
                }
                .bliz-plates button:hover { border-color: #00f5d4; }
                .bliz-plates button:focus-visible { outline: 2px solid #00f5d4; outline-offset: 3px; }
                .bliz-plates code {
                    display: block; max-height: 100px; overflow: auto;
                    overflow-wrap: anywhere; font-size: 12px; line-height: 1.5;
                    user-select: text;
                }
                .bliz-plates .copy-status { min-height: 20px; margin-top: 12px; }
            `}</style>
            <h2>Bliz Plates &amp; Frames</h2>
            <p>Click a code to copy it.</p>
            {plateCodes.map(({ label, code }) => (
                <section key={label}>
                    <h3>{label}</h3>
                    <button type="button" onClick={() => copyCode(code, label)} aria-label={`Copy ${label} code`}>
                        <code>{code}</code>
                    </button>
                </section>
            ))}
            <p className="copy-status" role="status">{message}</p>
        </div>
    );
}
